window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[32]={"id":"032","numero":32,"titre":"Prise en charge du nouveau-né","objectifs":[{"id":"32-1","rang":"B","rubrique":"Diagnostic positif","titre":"Évaluation clinique du nouveau-né à terme : connaître l’examen clinique du nouveau-né","contenu":"<p>L’examen du <span class=\"kw-def\">nouveau-né à terme</span> est <strong>obl<span class=\"kw-chiffre\">iga</span>toire avant le 8ᵉ jour de vie</strong> et permet d’établir le <strong>1ᵉʳ certificat de santé</strong> (« certificat du 8ᵉ jour »). Il s’effectue en présence de la mère (ou des 2 parents), dans une pièce claire et chauffée, de préférence avant un repas ou pendant un soin, lorsque l’enfant est éveillé, et dans le respect des règles d’hygiène.</p>\n\n      <h4>Constantes et paramètres à connaître</h4>\n\n      <table >\n        <thead>\n          <tr><th>Domaine</th><th>Valeurs normales</th><th>Signe d’alerte</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Poids · Taille · PC</strong></td>\n            <td>\n              <span class=\"kw-chiffre\">3 500 g</span> en moyenne (normales <span class=\"kw-chiffre\">2 500-4 200 g</span>)<br>\n              Taille <span class=\"kw-chiffre\">50 cm</span> (normales <span class=\"kw-chiffre\">46-52 cm</span>)<br>\n              PC <span class=\"kw-chiffre\">35 cm</span>\n            </td>\n            <td>Hors bornes → suspicion <span class=\"kw-etio\">RCIU</span> ou <span class=\"kw-etio\">macrosomie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Température</strong></td>\n            <td>Normo-thermie</td>\n            <td><span class=\"kw-alerte\">Fièvre ≥ 38 °C</span> = <span class=\"kw-alerte\">urgence</span> diagnostique, justifie ATB probabiliste</td>\n          </tr>\n          <tr>\n            <td><strong>FC au repos</strong></td>\n            <td><span class=\"kw-chiffre\">120-160 bpm</span></td>\n            <td>Absence de pouls fémoraux → évoquer <span class=\"kw-etio\">coarctation de l’aorte</span></td>\n          </tr>\n          <tr>\n            <td><strong>FR au repos</strong></td>\n            <td><span class=\"kw-chiffre\">40-60/min</span>, respiration <strong>nasale, silencieuse, régulière</strong>, parfois périodique</td>\n            <td><span class=\"kw-clinique\">Polypnée</span>, signes de lutte, désaturation</td>\n          </tr>\n          <tr>\n            <td><strong>TRC</strong></td>\n            <td><span class=\"kw-chiffre\">&lt; 3 s</span> au niveau du thorax</td>\n            <td>Allongement → bas débit, <span class=\"kw-alerte\">choc</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Examen général · viscéral · cordon</h4>\n\n      <ul>\n        <li><strong>Cardio-vasculaire :</strong> <span class=\"kw-clinique\">souffle systolique</span> non rare → justifie une <span class=\"kw-imagerie\">échographie cardiaque</span> et <span class=\"kw-def\">surveillance</span> ; souffle vasculaire de la fontanelle antérieure → évoquer une <span class=\"kw-etio\">malformation artério-veineuse</span></li>\n        <li><strong>Thorax :</strong> <span class=\"kw-clinique\">gynécomastie ± galactorrhée</span> possible (imprégnation hormonale passive in utero)</li>\n        <li><strong>Abdomen :</strong> souple, parfois météorisé ; foie palpable dépassant le rebord costal de <span class=\"kw-chiffre\">1-2 cm</span> ; pôle inférieur de rate / reins parfois perçus ; diastasis des grands droits banal ; <span class=\"kw-clinique\">hernie ombilicale</span> sans traitement (fermeture spontanée <span class=\"kw-chiffre\">&lt; 2 ans</span>)</li>\n        <li><strong>Cordon ombilical :</strong> <span class=\"kw-chiffre\">2 artères + 1 veine</span> (« <em>tu as de la veine d’avoir 2 artères</em> »). Chute en moyenne vers <span class=\"kw-chiffre\">J10</span>. <span class=\"kw-alerte\">Chute &gt; 1 mois</span> → rechercher un <span class=\"kw-clinique\">déficit immunitaire</span></li>\n        <li><strong>Urines :</strong> émission des 1ères urines <span class=\"kw-chiffre\">&lt; 24 h</span> ; miction en goutte-à-goutte chez le garçon → suspicion de <span class=\"kw-clinique\">malformation urétrale</span></li>\n        <li><strong>Selles :</strong> perméabilité anale vérifiée par l’émission du <strong>méconium</strong> dans un délai <span class=\"kw-chiffre\">&lt; 48 h</span></li>\n      </ul>\n\n      <h4>Examen des organes génitaux externes</h4>\n\n      <table >\n        <thead>\n          <tr><th>2 sexes</th><th>Garçon</th><th>Fille</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>\n              Vérifier l’absence d’<span class=\"kw-clinique\">anomalie de la différenciation sexuelle</span> dès <span class=\"kw-clinique\">les</span> 1ères heures :<br>\n              → ne pas déclarer un sexe erroné, ne pas méconnaître une <span class=\"kw-clinique\">hyperplasie congénitale des surrénales</span>\n            </td>\n            <td>\n              <strong>Prépuce rarement rétractable</strong> dans <span class=\"kw-clinique\">les</span> 1ères années → <strong>décalottage <span class=\"kw-ci\">interdit</span></strong> (risque de <span class=\"kw-alerte\">paraphimosis</span> et <span class=\"kw-alerte\">phimosis cicatriciel</span>).<br>\n              <strong>Hydrocèle</strong> (<span class=\"kw-clinique\">tuméfaction</span> scrotale transilluminable) fréquente, régression spontanée.<br>\n              <strong>Cryptorchidie :</strong> testicule palpable inguinal → chir péd pour abaissement entre <span class=\"kw-chiffre\">M6-1 an</span> ; non palpable → laparotomie exploratrice <span class=\"kw-chiffre\">6 mois - 1 an</span> ; bilatérale non palpable → pédiatre endocrinologue (caryotype + bilan endocrinien).\n            </td>\n            <td>\n              Vérifier la <strong>présence de l’orifice vaginal</strong>.<br>\n              <span class=\"kw-clinique\">Leucorrhées</span>, <span class=\"kw-clinique\">métrorragies</span> possibles, liées à la crise génitale.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Examen cutané — particularités sémiologiques non pathologiques</h4>\n\n      <table >\n        <thead>\n          <tr><th>Aspect</th><th>Description</th><th><span class=\"kw-clinique\">Évolution</span></th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Vernix caseosa</strong></td><td>Enduit blanc graisseux adhérent recouvrant la peau, surtout dans <span class=\"kw-clinique\">les</span> plis</td><td>Physiologique</td></tr>\n          <tr><td><strong>Desquamation</strong></td><td>Modérée, possible 1ers jours</td><td>Surtout chez le <span class=\"kw-clinique\">post-terme</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Œdèmes</span></strong></td><td>Paupières, dos mains/pieds, pubis, scrotum</td><td>Régressent en quelques jours</td></tr>\n          <tr><td><strong>Lanugo</strong></td><td>Fin duvet : front, dos, épaules</td><td>Disparaît en quelques jours</td></tr>\n          <tr><td><strong>Grains de milium</strong></td><td>Microkystes sébacés punctiformes blancs : nez, face</td><td>Physiologique</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Érythème</span> <span class=\"kw-etio\">toxique</span></strong></td><td><span class=\"kw-clinique\">Éruption</span> maculopapuleuse voire pustuleuse transitoire</td><td>Entre <span class=\"kw-chiffre\">H12</span> et <span class=\"kw-chiffre\">J4</span></td></tr>\n          <tr><td><strong>Tache mongoloïde</strong></td><td>Tache ardoisée <span class=\"kw-chiffre\">≈ 10 cm</span>, région lombosacrée ; populations asiatiques, méditerranéennes, africaines (≈ <span class=\"kw-chiffre\">1 %</span> des enfants à peau claire)</td><td>Disparaît dans <span class=\"kw-clinique\">les</span> 1ères années de vie</td></tr>\n          <tr><td><strong>Angiome plan physiologique</strong></td><td><strong>Rose saumon</strong> (plus pâle que <span class=\"kw-clinique\">les</span> angiomes plans en lie de vin) : glabelle, front, paupières, nez, occiput</td><td>Pâlissement en quelques mois (sauf nuque/occiput, possible persistance à l’âge adulte)</td></tr>\n          <tr><td><strong>Hémangiome</strong></td><td>Apparaît après quelques jours : superficiel (tubéreux) ou dermique profond</td><td>Régression progressive (<span class=\"kw-def\">suivi</span> pédiatrique)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Livedo</span></strong></td><td>Aspect marbré (immaturité de la vasorégulation) : membres, thorax</td><td>Physiologique</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Tête · face · neurosensoriel</h4>\n\n      <table >\n        <thead>\n          <tr><th></th><th>Bosse sérosanguine</th><th>Céphalhématome</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Fréquence</strong></td><td>Souvent observée</td><td>Plus rare (<span class=\"kw-chiffre\">0,5-1,5 %</span>)</td></tr>\n          <tr><td><strong>Description</strong></td><td>Collection <strong>sous-cutanée</strong>, <strong>molle</strong>, <strong>mal limitée</strong>, <strong>chevauchant <span class=\"kw-clinique\">les</span> sutures</strong></td><td>Collection <strong>sous-périostée</strong>, <strong>limitée par <span class=\"kw-clinique\">les</span> sutures</strong></td></tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td>Résorption en <span class=\"kw-chiffre\">2-6 jours</span></td>\n            <td>\n              Guérison spontanée le plus souvent ; complications possibles :<br>\n              <strong><span class=\"kw-clinique\">Ictère</span> :</strong> lié à la résorption sanguine, fréquent (anémie rare)<br>\n              <strong>Calcification :</strong> déformation crânienne en <span class=\"kw-chiffre\">4-6 semaines</span> (rare, <span class=\"kw-chiffre\">5 %</span>)<br>\n              <strong>Infection :</strong> de la poche sanguine (exceptionnelle)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <ul>\n        <li><strong>Fontanelles :</strong> antérieure losangique se ferme entre <span class=\"kw-chiffre\">8-18 mois</span> ; postérieure palpable <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2-3 premières semaines</span> (se ferme avant <span class=\"kw-chiffre\">2-3 mois</span>)</li>\n        <li><strong>Sutures :</strong> normalement bord à bord, mobiles ; peuvent se <strong>chevaucher</strong> <span class=\"kw-clinique\">les</span> premiers jours</li>\n        <li><strong>Cou :</strong> torticolis, hématome des sterno-cléïdo-mastoïdiens</li>\n        <li><strong>Bouche :</strong> rechercher <span class=\"kw-etio\">fente vélo-palatine</span>, brièveté du frein de langue</li>\n        <li><strong>Yeux :</strong> <span class=\"kw-clinique\">asymétrie</span> des reflets cornéens (strabisme possible avant <span class=\"kw-chiffre\">3 mois</span> si intermittent et alternant) ; <span class=\"kw-alerte\">absence de lueur pupillaire</span> (leucocorie) → <span class=\"kw-etio\">rétinoblastome</span>, <span class=\"kw-etio\">cataracte congénitale</span></li>\n        <li><strong>Oreille :</strong> pas de signe clinique fiable de surdité hors anomalie du pavillon → justifie le <strong><span class=\"kw-def\">dépistage</span> systématique par OEAP / PEAA</strong></li>\n        <li><strong>Sensorialité :</strong> réagit aux bruits/voix, cligne à la lumière, poursuite oculaire d’une cible noir/blanc à ≈ <span class=\"kw-chiffre\">30 cm</span></li>\n        <li><strong>Motricité :</strong> spontanée riche, symétrique, ouverture des mains, mouvements indépendants des doigts</li>\n        <li><strong>Comportement :</strong> éveil calme facile, réactivité vive avec cri franc, consolabilité (voix, bras, succion)</li>\n      </ul>\n\n      <h4>Examen ostéo-articulaire</h4>\n\n      <ul>\n        <li><strong>Rachis :</strong> palpation complète à la recherche d’une <span class=\"kw-clinique\">anomalie de fermeture du tube neural (spina bifida)</span> justifiant une <span class=\"kw-imagerie\">échographie médullaire</span> : déviation du sillon interfessier, pertuis / fossette sacrococcygienne profonde, lipome sous-cutané, touffe de poils, angiome cutané</li>\n        <li><strong>Hanche — recherche de luxation <span class=\"kw-etio\">congénitale</span> :</strong>\n          <ol>\n            <li>Limitation de l’abduction (volant d’abduction) si <span class=\"kw-chiffre\">&lt; 60°</span></li>\n            <li><strong>Manœuvre de Barlow :</strong> hanche en <strong>adduction - rotation externe</strong> + pression axiale sur le genou → recherche d’un <strong>ressaut de luxation</strong></li>\n            <li><strong>Manœuvre d’Ortolani :</strong> hanche en <strong>abduction - rotation interne</strong> + traction axiale + pression sur le grand trochanter → <strong>ressaut de <span class=\"kw-ttt\">réduction</span></strong></li>\n          </ol>\n        </li>\n        <li><strong>Extrémités :</strong> polydactylie, syndactylie, hypoplasies/aplasies des doigts ; distinguer <span class=\"kw-clinique\">les</span> déformations <strong>rigides malformatives</strong> (pied bot varus équin) des <strong>malpositions réductibles bénignes</strong> (pieds varus, clinodactylie)</li>\n        <li><strong>Lésions traumatiques per-partum :</strong> bosse sérosanguine, céphalhématome, hématomes cutanés ; <span class=\"kw-clinique\">paralysie faciale</span> (forceps), paralysie du plexus brachial ; fracture de clavicule ; <span class=\"kw-clinique\">purpura mécanique</span> face/vertex (extraction difficile, circulaire serrée)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent · 53 — Retard de croissance staturo-pondéral · 54 — Boiterie de l'enfant</em></p>","frequence":4},{"id":"32-2","rang":"B","rubrique":"Diagnostic positif","titre":"Évaluation clinique du nouveau-né à terme : connaître les critères pédiatriques de maturation d’un nouveau-né à terme","contenu":"<p>Un <span class=\"kw-def\">nouveau-né à terme</span> est né entre <span class=\"kw-chiffre\">37-41 SA</span>. L’<strong><span class=\"kw-def\">âge gestationnel</span> (AG)</strong> est d’abord déterminé en anténatal ; à défaut, la maturation est appréciée cliniquement par <span class=\"kw-clinique\">les</span> critères morphologiques et neurologiques.</p>\n\n      <h4>Détermination de l’AG</h4>\n\n      <ol>\n        <li><strong><span class=\"kw-imagerie\">Échographie</span> de <span class=\"kw-chiffre\">10-12 SA</span></strong> (précision <span class=\"kw-chiffre\">± 3-5 jours</span>) — méthode de référence</li>\n        <li><strong>Date des dernières règles</strong> à défaut (imprécise dans <span class=\"kw-chiffre\">20-30 %</span> des cas)</li>\n        <li>Si absence de critères obstétricaux → appréciation clinique par :\n          <ul>\n            <li><strong>Critères morphologiques :</strong> tissu mammaire, plis plantaires, cartilage auriculaire, aspect des OGE</li>\n            <li><strong>Examen neurologique :</strong> tonus + automatismes primaires</li>\n          </ul>\n        </li>\n      </ol>\n\n      <h4>Tonus passif</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Principe.</strong> <span class=\"kw-chiffre\">Plus l’enfant est mature, plus sa posture passive est en <strong>flexion</strong></span>. Le nouveau-né à terme est en <strong><span class=\"kw-def\">quadriflexion</span></strong> spontanée (prépondérance des fléchisseurs).\n      </div>\n\n      <table >\n        <thead>\n          <tr><th>Manœuvre</th><th>Valeur normale au terme</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Retour en flexion</strong></td><td>Après extension des MS par l’examinateur → retour rapide en flexion</td></tr>\n          <tr><td><strong>Signe du foulard</strong></td><td>Main rapprochée de l’épaule controlatérale → <strong>coude ne dépasse pas la ligne médiane</strong></td></tr>\n          <tr><td><strong>Angle poplité</strong></td><td><span class=\"kw-chiffre\">≤ 90°</span></td></tr>\n          <tr><td><strong>Angle des adducteurs</strong></td><td><span class=\"kw-chiffre\">40-70°</span></td></tr>\n          <tr><td><strong>Angle de dorsiflexion du pied</strong></td><td><span class=\"kw-chiffre\">0-20°</span></td></tr>\n          <tr><td><strong>Angle talon-oreille</strong></td><td><span class=\"kw-chiffre\">≤ 90°</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Tonus actif</h4>\n\n      <ul>\n        <li><strong>Manœuvre du tiré-assis :</strong> tenir l’enfant par <span class=\"kw-clinique\">les</span> épaules → teste les <span class=\"kw-clinique\">muscles fléchisseurs du cou</span> (tiré) puis les <span class=\"kw-clinique\">extenseurs du cou</span> (assis). Réponse normale : <strong>tête maintenue dans l’axe quelques secondes</strong>, réponse symétrique.</li>\n        <li><strong>Manœuvre du redressement global :</strong> suspension ventrale (thorax soutenu) → l’enfant <strong>redresse ses MI, puis son tronc et sa tête</strong> quelques secondes.</li>\n      </ul>\n\n      <h4>Automatismes primaires (<span class=\"kw-def\">réflexes archaïques</span>)</h4>\n\n      <div class=\"callout callout-warn\">\n        <strong>Règle clé.</strong> Leur <strong>absence est toujours pathologique</strong>. Leur présence ne témoigne en revanche <strong>pas</strong> de l’intégrité du SNC. Ils disparaissent entre <span class=\"kw-chiffre\">2-4 mois</span> de vie.\n      </div>\n\n      <table >\n        <thead>\n          <tr><th>Réflexe</th><th>Stimulus</th><th>Réponse normale</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Succion</strong></td><td>Tétine / mamelon</td><td><strong>Intense, rythmée, sans fatigue ni changement de teint</strong></td></tr>\n          <tr><td><strong>Points cardinaux</strong></td><td>Stimulation des commissures labiales</td><td>Rotation de la tête + ouverture de la bouche, l’enfant cherche à téter</td></tr>\n          <tr><td><strong>Agrippement (grasping)</strong></td><td>Stimulation de la paume (ou plante)</td><td>Flexion spontanée des doigts/orteils + agrippement du doigt de l’examinateur</td></tr>\n          <tr><td><strong>Moro</strong></td><td>Extension brutale de la nuque</td><td>Extension des 4 membres + ouverture des mains ± cri</td></tr>\n          <tr><td><strong>Allongement croisé</strong></td><td>Stimulation de la plante d’un pied (MI maintenu en extension)</td><td>Retrait (flexion) puis <strong>extension du MI controlatéral</strong></td></tr>\n          <tr><td><strong>Marche automatique</strong></td><td>Soutenu au tronc, debout penché en avant, <span class=\"kw-def\">contact</span> plante / table</td><td>Réflexe de retrait en alternance des MI → impression de marche</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent</em></p>","frequence":4},{"id":"32-3","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la prise en charge en salle de naissance","contenu":"<p>Chaque naissance nécessite la <strong>présence d’<span class=\"kw-chiffre\">≥ 1</span> personne entraînée</strong> (sage-femme ou pédiatre) aux 1ers gestes de prise en charge, s’occupant <strong>uniquement de ce nouveau-né</strong> (une personne par enfant en cas de naissances multiples).</p>\n\n      <h4>Évaluation de l’adaptation à la vie extra-utérine — <span class=\"kw-def\">Score</span> d’<span class=\"kw-def\">Apgar</span></h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Quand ?</strong> À <span class=\"kw-chiffre\">1 minute</span>, <span class=\"kw-chiffre\">5 minutes</span> et <span class=\"kw-chiffre\">10 minutes</span> de vie. <strong><span class=\"kw-def\">Score</span> normal <span class=\"kw-chiffre\">≥ 7.</span></strong><br>\n        <strong>CAT si inadaptation :</strong> <span class=\"kw-alerte\">manœuvres de réanimation</span> (concerne <span class=\"kw-chiffre\">5-10 %</span> des nouveau-nés).\n      </div>\n\n      <table >\n        <thead>\n          <tr><th>Paramètre</th><th>0</th><th>1</th><th>2</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Apparence (coloration)</strong></td><td>Globalement <strong>bleue</strong> ou <strong>pâle</strong></td><td>Corps rose + extrémités bleues</td><td>Globalement <strong>rose</strong></td></tr>\n          <tr><td><strong>Pouls (FC)</strong></td><td>Absents</td><td>FC <span class=\"kw-chiffre\">&lt; 100 bpm</span></td><td>FC <span class=\"kw-chiffre\">≥ 100 bpm</span></td></tr>\n          <tr><td><strong>Grimace (réactivité)</strong></td><td>Nulle</td><td>Faible (grimace)</td><td>Vive (cris, <span class=\"kw-clinique\">toux</span>)</td></tr>\n          <tr><td><strong>Activité (tonus)</strong></td><td>Nul</td><td>Faible (légère flexion des extrémités)</td><td>Fort (<span class=\"kw-def\">quadriflexion</span>, mouvements actifs)</td></tr>\n          <tr><td><strong>Respiration</strong></td><td>Absente</td><td>Lente, irrégulière</td><td><strong>Vigoureuse</strong> avec <strong>cris</strong></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Soins initiaux systématiques</h4>\n\n      <table >\n        <thead>\n          <tr><th>Temps</th><th>Gestes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1ᵉʳ temps</strong><br>(à la naissance)</td>\n            <td>\n              <strong>Clampage + section du cordon</strong> aux ciseaux stériles (après <span class=\"kw-clinique\">les</span> premiers cris si vigoureux)<br>\n              <strong>Évaluation de la vitalité</strong> par le <span class=\"kw-def\">score</span> d’<span class=\"kw-def\">Apgar</span> à 1, 5 et <span class=\"kw-chiffre\">10 min</span><br>\n              <strong>Mise au sein</strong> dans la 1ère heure de vie si la mère souhaite allaiter<br>\n              <strong>Prévention de l’<span class=\"kw-clinique\">hypothermie</span></strong> (essentielle) : atmosphère chaude (<span class=\"kw-chiffre\">≈ 24 °C</span>) ; séchage soigneux avec linge propre stérile ; bonnet ; <span class=\"kw-ttt\">peau à peau</span> sur la poitrine de la mère (ou table radiante si soins urgents)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2ⁿᵈ temps</strong><br>(avant le départ de la salle de naissance)</td>\n            <td>\n              <strong>Vitamine K1 per os</strong><br>\n              <strong>Bracelets d’identification</strong><br>\n              <strong>Examen clinique initial</strong> + mesure des paramètres de naissance (TN, PN, PCN)<br>\n              <strong>Soins du cordon ombilical</strong> + vérification de <span class=\"kw-chiffre\">2 artères + 1 veine</span> (« <em>tu as de la veine d’avoir 2 artères</em> »)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Soins initiaux non systématiques (selon contexte)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Geste</th><th>Indication</th><th>Objectif</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>ATB conjonctival</strong> (collyre)</td>\n            <td>ATCD ou FR d’<span class=\"kw-clinique\">IST</span> chez <span class=\"kw-clinique\">les</span> parents (<span class=\"kw-ci\">grossesse</span> non/mal suivie)</td>\n            <td>Prévention conjonctivite néonatale</td>\n          </tr>\n          <tr>\n            <td><strong>Sonde d’aspiration</strong></td>\n            <td><span class=\"kw-clinique\">Dyspnée inspiratoire</span> · <span class=\"kw-clinique\">désaturation qui se lève aux cris</span></td>\n            <td>Rechercher une <span class=\"kw-alerte\">atrésie des choanes</span></td>\n          </tr>\n          <tr>\n            <td><strong>Test à la seringue</strong></td>\n            <td>Hypersialorrhée · gêne respiratoire · hydramnios ou malformation diagnostiqués en anténatal</td>\n            <td>\n              Éliminer une <span class=\"kw-alerte\">atrésie de l’œsophage</span> :<br>\n              <strong>Principe :</strong> injecter rapidement de l’<span class=\"kw-def\">air</span> dans une sonde orogastrique, rechercher un bruit aérique au creux ép<span class=\"kw-chiffre\">iga</span>strique (<strong>absent</strong> si atrésie)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 24 — Complications de la grossesse · 27 — Prévention risques fœtaux · 31 — Accouchement - suites de couche normales</em></p>","frequence":2},{"id":"32-4","rang":"B","rubrique":"Prise en charge","titre":"Connaître les dépistages systématiques néonatals","contenu":"<div class=\"callout callout-info\">\n        <strong>Objectif phare 🔥</strong> — 6 ⭐ bruts au tableau EDN, cappées à 5. C’est <strong>l’objectif le plus tombable de l’item</strong> avec obj-6.\n      </div>\n\n      <h4>Test de Guthrie — programme national</h4>\n\n      <p>Le programme répond aux <span class=\"kw-def\">critères OMS du dépistage</span> : problème de santé publique, maladie fréquente/grave, <span class=\"kw-def\">physiopathologie</span> connue avec <span class=\"kw-clinique\">évolution</span> grave sans traitement, test fiable et reproductible, peu coûteux, acceptable.</p>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Quand ?</strong></td><td>Systématiquement autour de <span class=\"kw-chiffre\">72 h</span> de vie (impérativement <span class=\"kw-chiffre\">&gt; 48 h</span>, au mieux avant la sortie de maternité)</td></tr>\n          <tr><td><strong>Prélèvement</strong></td><td><strong>Papier buvard</strong> nominatif, 8-<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>10</span> g</span>outtes de sang (<span class=\"kw-ttt\">ponction</span> capillaire au talon)</td></tr>\n          <tr><td><strong>Consentement</strong></td><td><strong>Écrit, sollicité avant le prélèvement</strong> (car <span class=\"kw-def\">dépistage</span> mucoviscidose requiert étude <span class=\"kw-etio\">génétique</span> si trypsine élevée). Test <strong>non obl<span class=\"kw-chiffre\">iga</span>toire</strong> — <span class=\"kw-clinique\">les</span> parents peuvent refuser en signant une décharge.</td></tr>\n          <tr><td><strong>Information parents</strong></td><td><span class=\"kw-clinique\">Les</span> parents ne sont avertis <strong>qu’en cas de résultat anormal</strong></td></tr>\n          <tr><td><strong>Coût</strong></td><td>Intégralement financé par l’Assurance maladie</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-clinique\">Les</span> 6 maladies dépistées</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Mémo « PM-HH-DD »</strong> · <strong>P</strong>hénylcétonurie · <strong>M</strong>ucoviscidose · <strong>H</strong>ypothyroïdie · <strong>H</strong>yperplasie <span class=\"kw-etio\">congénitale</span> des surrénales · <strong>D</strong>éficit en MCAD · <strong>D</strong>répanocytose.\n      </div>\n\n      <table >\n        <thead>\n          <tr><th>Maladie</th><th>Marqueur</th><th>Particularités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Phénylcétonurie (PCU)</strong></td>\n            <td><span class=\"kw-bio\">Phénylalanine</span></td>\n            <td>Déficit en <strong>phénylalanine hydroxylase</strong> · transmission <span class=\"kw-clinique\">autosomique récessive</span> · <span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">1/16 000</span> · risque sans traitement : <span class=\"kw-alerte\">retard psychomoteur sévère</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Hypothyroïdie</span> <span class=\"kw-etio\">congénitale</span></strong></td>\n            <td><span class=\"kw-bio\">TSH</span></td>\n            <td>\n              Fréquence <span class=\"kw-chiffre\">1/2 500</span> sur <span class=\"kw-clinique\">les</span> dernières années · étiologies : trouble de l’hormonogenèse, dysgénésies (athyréose, <strong>thyroïde ectopique</strong> ++, hypoplasie)<br>\n              <strong>Manifestations à diagnostic :</strong> <span class=\"kw-clinique\">constipation</span>, <span class=\"kw-clinique\">ictère</span> prolongé à <span class=\"kw-bio\">bilirubine</span> libre, macroglossie, pleurs rauques, difficultés à la succion, <span class=\"kw-clinique\">hypothermie</span>, hypotonie, fontanelles larges (postérieure surtout)<br>\n              <strong>Traitement à vie :</strong> <span class=\"kw-ttt\">L-thyroxine</span> ≥ <span class=\"kw-chiffre\">10 µg/kg/j</span>, <strong>avant <span class=\"kw-chiffre\">12-15 jours</span></strong> → <span class=\"kw-def\">pronostic</span> transformé (plus de retard mental, croissance normale)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hyperplasie <span class=\"kw-etio\">congénitale</span> des surrénales</strong></td>\n            <td><span class=\"kw-bio\">17-OH-progestérone</span></td>\n            <td>\n              Déficit en <strong>21-hydroxylase</strong> (&gt; <span class=\"kw-chiffre\">95 %</span> des HCS, forme classique) · <span class=\"kw-clinique\">autosomique récessive</span> · <span class=\"kw-chiffre\">1/15 000</span><br>\n              Conséquences : <strong>insuffisance surrénale</strong> (cortisol + aldostérone) ± <strong>ambiguïté sexuelle chez la fille</strong> (déviation vers androgènes)<br>\n              <strong>Forme classique :</strong> insuffisance surrénale aiguë (<span class=\"kw-clinique\">déshydratation</span> + <span class=\"kw-bio\">hyponatrémie</span> + <span class=\"kw-bio\">hyperkaliémie</span> + hypoglycémie + troubles digestifs) ± virilisation des OGE (hyperplasie du clitoris, fusion des grandes lèvres)<br>\n              <strong>Forme non classique :</strong> enzyme partiellement active → révélation tardive (hirsutisme, hyperandrogénie)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mucoviscidose</strong></td>\n            <td><span class=\"kw-bio\">Trypsine immunoréactive (TIR)</span></td>\n            <td>\n              Généralisé depuis 2002 · prélèvement à <span class=\"kw-chiffre\">72 h</span> · consentement signé (étude <span class=\"kw-etio\">génétique</span>)<br>\n              <strong>Performances :</strong> sensibilité bonne (FN <span class=\"kw-chiffre\">3-3,5 %</span>), <strong>spécificité faible</strong> (4/5 enfants convoqués au CRCM n’ont pas la mucoviscidose)<br>\n              <strong>CAT si TIR élevé :</strong> recherche des <span class=\"kw-chiffre\">29</span> mutations CFTR <span class=\"kw-clinique\">les</span> plus fréquentes →\n              <ul>\n                <li><strong>Aucune mutation :</strong> nouveau dosage TIR à <span class=\"kw-chiffre\">3 semaines</span> → CRCM si élevé</li>\n                <li><strong>Mutation sur <span class=\"kw-chiffre\">≥ 1</span> allèle :</strong> convocation CRCM pour <strong>test de la sueur</strong></li>\n              </ul>\n              <strong>Manifestations néonatales possibles :</strong> <span class=\"kw-clinique\">ictère</span> cholestatique rétentionnel, <span class=\"kw-alerte\">iléus méconial</span> (occlusion iléale par méconium visqueux, lavage ± <span class=\"kw-ttt\">chirurgie</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Déficit en MCAD</strong></td>\n            <td><span class=\"kw-bio\">Octanoyl-carnitine (C8)</span> par spectrométrie de <span class=\"kw-clinique\">masse</span></td>\n            <td>Anomalie la plus fréquente de la β-oxydation des AG · <span class=\"kw-clinique\">autosomique récessive</span> (gène <em>ACADM</em>) · <span class=\"kw-chiffre\">1/15 000</span> · manifestations : <span class=\"kw-alerte\">malaises hypoglycémiques hypocétosiques au jeûne long</span></td>\n          </tr>\n          <tr>\n            <td><strong>Drépanocytose</strong></td>\n            <td><span class=\"kw-bio\">Électrophorèse de l’hémoglobine S</span></td>\n            <td>\n              Mutation chaîne β → <strong>HbS</strong> · <strong>généralisation HAS à toute la population</strong> (auparavant ciblé : Afrique subsaharienne, Antilles, Guyane, Réunion, bassin méditerranéen)<br>\n              Réalisé <strong>à distance de toute transfusion</strong> · formes : SS (HbA = 0), S-β⁰ (HbS + HbF), SC (HbS + HbC)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>+ 7 erreurs innées du métabolisme (depuis 2023)</h4>\n\n      <ul>\n        <li><strong>3 amino-acidopathies :</strong> homocystinurie · leucinose · tyrosinémie de type 1</li>\n        <li><strong>2 aciduries organiques :</strong> acidurie glutarique de type 1 · acidurie isovalérique</li>\n        <li><strong>2 déficits de la β-oxydation des AG :</strong> déficit en captation de carnitine · déficit en <strong>LCHAD</strong> (3-hydroxyacyl-coA déshydrogénase des AG à chaînes longues)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent · 53 — Retard de croissance staturo-pondéral</em></p>","frequence":5},{"id":"32-5","rang":"B","rubrique":"Prise en charge","titre":"Connaître les autres dépistages","contenu":"<p>Au-delà du Guthrie sanguin, <strong>3 dépistages systématiques</strong> complètent la maternité.</p>\n\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Dépistage</span></th><th>Modalités</th><th>CAT si anormal</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Luxation congénitale de hanche</span></strong></td>\n            <td><strong>Systématique à chaque examen</strong> (cf. obj-0) : volant d’abduction, manœuvre de Barlow, manœuvre d’Ortolani</td>\n            <td><span class=\"kw-imagerie\">Échographie</span> de hanche, avis orthopédiste pédiatrique, langeage en abduction / orthèse</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Surdité congénitale</span></strong></td>\n            <td>\n              <strong>OEAP</strong> (otoémissions acoustiques provoquées, <span class=\"kw-chiffre\">5 %</span> FP) <strong>et/ou PEAA</strong> (potentiels évoqués auditifs automatisés, <span class=\"kw-chiffre\">1 %</span> FP), à partir de <strong><span class=\"kw-chiffre\">J3</span></strong>, idéalement avant la sortie de maternité<br>\n              <strong>Pré-requis :</strong> enfant endormi/calme, pièce silencieuse\n            </td>\n            <td>\n              Si <strong>anormal à 2 reprises</strong> en maternité → adressé à un <strong>spécialiste ORL</strong> pour contrôle.<br>\n              Si toujours anormal → <strong>centre d’audiologie pédiatrique</strong> pour étape diagnostique (audiogramme + PEA, qui deviennent alors diagnostiques et non plus de <span class=\"kw-def\">dépistage</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Vision · anomalies oculaires</strong></td>\n            <td>Recherche systématique d’anomalies de l’examen des yeux et de la fonction visuelle (lueur pupillaire +++, reflets cornéens, poursuite oculaire)</td>\n            <td>Avis ophtalmo en cas de leucocorie (<span class=\"kw-etio\">rétinoblastome</span>, <span class=\"kw-etio\">cataracte congénitale</span>) ou de strabisme fixé / non alternant</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique OEAP.</strong> <span class=\"kw-clinique\">Les</span> OEAP <strong>ne repèrent pas toutes les surdités</strong> ⚠️ : elles peuvent être présentes (réponse normale au test) chez un enfant <strong>réellement sourd</strong> (neuropathie auditive). Le <span class=\"kw-def\">dépistage</span> négatif ne dispense donc pas de réévaluer cliniquement l’audition dans les mois et années qui suivent.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent · 81 — Altération chronique de la vision</em></p>","frequence":0},{"id":"32-6","rang":"A","rubrique":"Prise en charge","titre":"Promouvoir la qualité des premiers liens affectifs parents-enfant et expliquer les bases de la puériculture","contenu":"<p>L’information aux parents s’intègre dans une approche <span class=\"kw-def\">globale et bienveillante</span>, du <span class=\"kw-ttt\">peau à peau</span> à la sortie de maternité, puis dans la prévention domiciliaire.</p>\n\n      <h4>Premiers liens affectifs & <span class=\"kw-ci\">allaitement</span> maternel</h4>\n\n      <ul>\n        <li><strong>Lien affectif dès la salle de naissance :</strong> <span class=\"kw-def\">contact</span> <span class=\"kw-ttt\">peau à peau</span> privilégié <strong>quel que soit le mode d’accouchement</strong>, <span class=\"kw-ttt\">mise au sein précoce</span> si la mère souhaite allaiter, premiers soins <strong>en présence des parents</strong></li>\n        <li><strong>Soutien à la parentalité :</strong> <span class=\"kw-clinique\">les</span> suites de couches sont un lieu d’apprentissage → accompagner les soins au nouveau-né pour <strong>accroître la confiance des parents</strong></li>\n        <li><strong>Bénéfices de l’<span class=\"kw-ttt\">allaitement maternel</span> :</strong>\n          <ul>\n            <li><strong>Enfant :</strong> modèle nutritionnel adapté · ↓ risque <span class=\"kw-etio\">infectieux</span> (<span class=\"kw-etio\">gastroentérites</span>, <span class=\"kw-etio\">otites</span>, infections respiratoires) · prévention des maladies atopiques (<span class=\"kw-def\">asthme</span>, <span class=\"kw-clinique\">dermatite</span> <span class=\"kw-etio\">atopique</span>) · interactions mère-enfant</li>\n            <li><strong>Mère :</strong> ↓ <span class=\"kw-etio\">diabète de type 2</span>, <span class=\"kw-etio\">cancer du sein</span> et de l’ovaire · perte de poids post-<span class=\"kw-ci\">grossesse</span></li>\n          </ul>\n        </li>\n        <li><strong><span class=\"kw-ci\">Allaitement</span> exclusif :</strong> recommandé par l’<span class=\"kw-def\">OMS</span> pendant <span class=\"kw-chiffre\">6 mois</span> — le choix revient à la mère (≈ <span class=\"kw-chiffre\">70 %</span> des mères françaises allaitent à la sortie de maternité)</li>\n        <li><strong>Supplémentations systématiques :</strong>\n          <ul>\n            <li><span class=\"kw-ttt\">Vitamine D</span> <span class=\"kw-chiffre\">1 000–1 200 UI/j</span> — <strong>quel que soit le mode d’alimentation</strong></li>\n            <li><span class=\"kw-ttt\">Vitamine K</span> <span class=\"kw-chiffre\">2 mg per os à 1 mois</span> de vie si <strong><span class=\"kw-ci\">allaitement</span> maternel exclusif</strong> (prévention de la maladie <span class=\"kw-etio\">hémorragique</span> tardive)</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>À la sortie de maternité — ordonnance et carnet</h4>\n\n      <ul>\n        <li><strong>Mise à jour du <span class=\"kw-def\">carnet de santé</span></strong> obl<span class=\"kw-chiffre\">iga</span>toire (examen clinique, régime alimentaire choisi, poids de sortie, dates des dépistages)</li>\n        <li><strong>Ordonnance de sortie :</strong>\n          <ul>\n            <li><strong>Soins du cordon ombilical</strong> jusqu’à sa chute</li>\n            <li><strong><span class=\"kw-ttt\">Supplémentations vitaminiques</span></strong> recommandées</li>\n            <li><strong>Prescription d’un régime précis</strong> par alimentation lactée</li>\n          </ul>\n        </li>\n        <li><strong>Organisation de la <span class=\"kw-def\">surveillance</span> :</strong>\n          <ul>\n            <li><span class=\"kw-def\">Surveillance</span> du poids : <span class=\"kw-chiffre\">1×/semaine durant le 1er mois</span> en cas d’<span class=\"kw-ci\">allaitement</span> maternel</li>\n            <li>Consultation pédiatre : recommandée au cours de la <span class=\"kw-chiffre\">2ᵉ semaine de vie</span></li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>Conseils de base de puériculture</h4>\n\n      <table >\n        <thead>\n          <tr><th>Domaine</th><th>Recommandation</th><th>Erreur <span class=\"kw-ci\">à éviter</span></th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Change</strong></td><td>Après chaque tétée</td><td>—</td></tr>\n          <tr><td><strong>Toilette vulvaire (fille)</strong></td><td>De <strong>haut en bas</strong> pour éviter la contamination par <span class=\"kw-clinique\">les</span> selles</td><td>Sens inversé → contamination fécale</td></tr>\n          <tr><td><strong>Oreilles</strong></td><td>Recueillir <span class=\"kw-clinique\">les</span> sécrétions au niveau du <strong>pavillon</strong></td><td><strong>Ne pas utiliser de coton-t<span class=\"kw-chiffre\">ige</span></strong></td></tr>\n          <tr><td><strong>Verge (garçon)</strong></td><td>Prépuce rarement rétractable <span class=\"kw-clinique\">les</span> 1ères années</td><td><strong>Ne pas décalotter</strong> (risque paraphimosis / phimosis cicatriciel)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Prévention dans <span class=\"kw-clinique\">les</span> 1ères années de vie (MIN +++)</h4>\n\n      <div class=\"callout callout-warn\">\n        <strong>Apporter toujours le <span class=\"kw-def\">carnet de santé</span></strong> en consultation. <strong>Consultation rapide</strong> si : <span class=\"kw-alerte\">fièvre 🔥 avant 3 mois</span> · difficultés alimentaires · gêne respiratoire · <span class=\"kw-clinique\">diarrhée</span> · <span class=\"kw-clinique\">vomissements</span> · comportement inhabituel.\n      </div>\n\n      <ul>\n        <li><strong>Protéger du soleil</strong>, ne pas laisser seul dans voiture/maison, <strong>ne pas secouer</strong></li>\n        <li>Informer sur <span class=\"kw-clinique\">les</span> <strong>risques du <span class=\"kw-etio\">tabagisme passif</span></strong> (MIN, <span class=\"kw-def\">asthme</span> du nourrisson)</li>\n        <li>Prévention de la transmission d’infection : <strong>lavage des mains</strong>, évitement des personnes enrhumées</li>\n        <li><strong>Prévention des <span class=\"kw-def\">accidents domestiques</span> :</strong>\n          <ul>\n            <li><strong>Chutes :</strong> fenêtres, escaliers</li>\n            <li><strong>Noyade :</strong> bain, piscine</li>\n            <li><strong><span class=\"kw-alerte\">Asphyxie</span> :</strong> sacs plastiques</li>\n            <li><strong>Inhalation de corps étrangers :</strong> petits aliments et objets</li>\n            <li><strong>Brûlures :</strong> bain trop chaud, lait chauffé au micro-ondes, prises électriques</li>\n            <li><strong>Intoxications :</strong> médicaments, produits d’entretien</li>\n          </ul>\n        </li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent · 55 — Développement psychomoteur · 56 — Enfant handicapé</em></p>","frequence":1},{"id":"32-7","rang":"B","rubrique":"Diagnostic positif","titre":"Reconnaître les situations à risque et les situations pathologiques nécessitant une prise en charge spécialisée","contenu":"<div class=\"callout callout-info\">\n        <strong>Objectif phare 🔥</strong> — <strong>8 ⭐ bruts</strong> au tableau EDN (cappées à 5), record de l’item. C’est l’objectif transversal qui ex<span class=\"kw-chiffre\">ige</span> de croiser anamnèse maternelle, sémiologie néonatale et orientation spécialisée.\n      </div>\n\n      <h4>Anamnèse — dossier obstétrical à parcourir systématiquement</h4>\n\n      <ul>\n        <li><strong>ATCD familiaux</strong> et particulièrement ceux de la mère (gynéco-obstétricaux et médicaux)</li>\n        <li><strong>État clinique de la mère</strong> (dont <span class=\"kw-clinique\">signes d’infection</span>)</li>\n        <li><strong>Échographies</strong>, <span class=\"kw-def\">suivi</span> de la <span class=\"kw-ci\">grossesse</span></li>\n        <li><strong>Monitoring cardiaque fœtal</strong> durant l’accouchement, <strong>terme</strong> (<span class=\"kw-def\">âge gestationnel</span>)</li>\n      </ul>\n\n      <h4>Drapeaux cliniques au nouveau-né — orienter vers une PEC spécialisée</h4>\n\n      <table >\n        <thead>\n          <tr><th>Signe / Contexte</th><th>Hypothèse à évoquer</th><th>Orientation</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Fièvre ≥ 38 °C</span></td><td><span class=\"kw-def\">Sepsis</span> néonatal · INBP</td><td><span class=\"kw-alerte\">Urgence</span> — bilan <span class=\"kw-etio\">infectieux</span> + ATB probabiliste (voir <strong>Zoom 2 — INBP</strong> ci-dessous)</td></tr>\n          <tr><td><span class=\"kw-def\">Apgar</span> &lt; <span class=\"kw-chiffre\">7 à 5-10 min</span></td><td>Inadaptation à la vie extra-utérine (<span class=\"kw-chiffre\">5-10 %</span> des NN)</td><td>Manœuvres de <span class=\"kw-alerte\">réanimation</span> néonatale</td></tr>\n          <tr><td><span class=\"kw-clinique\">Dyspnée</span> inspiratoire, désaturation qui se lève aux cris</td><td><span class=\"kw-alerte\">Atrésie des choanes</span></td><td>Sonde d’aspiration, ORL pédiatrique</td></tr>\n          <tr><td>Hypersialorrhée, gêne respiratoire, hydramnios ou malformation antenatale</td><td><span class=\"kw-alerte\">Atrésie de l’œsophage</span></td><td>Test à la seringue, <span class=\"kw-ttt\">chirurgie</span> pédiatrique</td></tr>\n          <tr><td>Absence de pouls fémoraux</td><td><span class=\"kw-etio\">Coarctation de l’aorte</span></td><td><span class=\"kw-imagerie\">Échographie cardiaque</span> urgente</td></tr>\n          <tr><td>Souffle de la fontanelle antérieure</td><td><span class=\"kw-etio\">Malformation artério-veineuse</span></td><td>Imagerie cérébrale, neuropédiatrie</td></tr>\n          <tr><td>Leucocorie (absence de lueur pupillaire)</td><td><span class=\"kw-etio\">Rétinoblastome</span>, cataracte <span class=\"kw-etio\">congénitale</span></td><td>Ophtalmo urgente</td></tr>\n          <tr><td>Chute du cordon &gt; <span class=\"kw-chiffre\">1 mois</span></td><td><span class=\"kw-clinique\">Déficit immunitaire</span></td><td>Bilan immunitaire spécialisé</td></tr>\n          <tr><td>Pas d’émission d’urines &lt; <span class=\"kw-chiffre\">24 h</span> ou méconium &lt; <span class=\"kw-chiffre\">48 h</span></td><td>Uropathie · obstruction digestive (<span class=\"kw-clinique\">iléus</span> méconial mucoviscidose)</td><td>Néphro / chir pédiatrique — cf. <strong>item 354</strong></td></tr>\n          <tr><td>Spina bifida, fossette sacrococcygienne profonde, lipome SC, touffe de poils</td><td>Anomalie de fermeture du tube neural</td><td><span class=\"kw-imagerie\">Échographie</span> médullaire, neurochir pédiatrique</td></tr>\n          <tr><td>Ambiguïté sexuelle des OGE</td><td><span class=\"kw-alerte\">Hyperplasie congénitale des surrénales</span> (forme classique)</td><td>Endocrinopédiatre dès <span class=\"kw-clinique\">les</span> 1ères heures, ne pas déclarer un sexe par défaut</td></tr>\n          <tr><td><span class=\"kw-alerte\">Détresse</span> respiratoire (geignement, <span class=\"kw-alerte\">tirage</span>, BAN, FR &gt; 60)</td><td>Maladie des membranes hyalines · <span class=\"kw-clinique\">tachypnée</span> transitoire · <span class=\"kw-imagerie\">pneumothorax</span> · inhalation méconiale · INBP</td><td>Réa néonatale — voir <strong>item 359</strong> et fiche source « <span class=\"kw-alerte\">Détresse</span> respiratoire du nouveau-né (203) & (359) »</td></tr>\n          <tr><td>FR de chorioamniotite, <span class=\"kw-alerte\">rupture</span> prolongée des membranes, prélèvements maternels positifs</td><td><span class=\"kw-alerte\">Infection néonatale bactérienne précoce (INBP)</span></td><td>Bilan <span class=\"kw-etio\">infectieux</span> + ATB probabiliste — voir fiche source dédiée du dossier 32</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Zoom 1 — <span class=\"kw-alerte\">Détresse</span> respiratoire du nouveau-né <span class=\"q\">(transversal items 203 &amp; 359)</span></h4>\n\n      <p>Quantifier la lutte respiratoire par le <span class=\"kw-def\">score de Silverman</span> — mémo <em>« <strong>Bé</strong>Bé <strong>Tire</strong> <strong>En</strong> <strong>Geignant</strong> »</em> (Battement des ailes du nez, Balancement thoraco-abdominal, <span class=\"kw-alerte\">Tirage</span>, Entonnoir xyphoïdien, Geignement).</p>\n\n      <table >\n        <thead>\n          <tr><th>Critère <span class=\"q\">(mémo)</span></th><th>0</th><th>1</th><th>2</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Battement des ailes du nez</strong> <span class=\"q\">(Bé)</span></td><td>Absent</td><td>Modéré</td><td>Intense</td></tr>\n          <tr><td><strong>Balancement thoraco-abdominal</strong> <span class=\"q\">(Bé)</span></td><td>Soulèvement synchrone</td><td>Thorax immobile</td><td><span class=\"kw-alerte\">Respiration paradoxale</span></td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Tirage</span> intercostal</strong> <span class=\"q\">(Tire)</span></td><td>Absent</td><td>Modéré</td><td>Intense</td></tr>\n          <tr><td><strong>Entonnoir xyphoïdien</strong> <span class=\"q\">(En)</span></td><td>Absent</td><td>Modéré</td><td>Intense</td></tr>\n          <tr><td><strong>Geignement expiratoire</strong> <span class=\"q\">(Geignant)</span></td><td>Absent</td><td>Audible au <strong>stéthoscope</strong></td><td>Audible <strong>à l’oreille</strong></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Signes de gravité</span>.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">FR &gt; 60/min</span> ; <span class=\"kw-alerte\">pauses respiratoires</span> = signe d’épuisement</li>\n          <li><span class=\"kw-clinique\">Cyanose</span> généralisée — reconnue en général pour une <span class=\"kw-bio\">SpO₂ &lt; 85 %</span></li>\n          <li><span class=\"kw-clinique\">Cyanose réfractaire</span> <em>sans</em> <span class=\"kw-alerte\">détresse</span> respiratoire associée → évoquer une <span class=\"kw-alerte\">HTAP</span> ou une <span class=\"kw-alerte\">cardiopathie cyanogène</span> (T4F, TGV)</li>\n        </ul>\n      </div>\n\n      <h4>Étiologies à confronter au contexte</h4>\n\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Contexte évocateur</th><th>Clinique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Retard de résorption</strong> du liquide pulmonaire <span class=\"q\">(<span class=\"kw-clinique\">tachypnée</span> transitoire)</span></td><td>Césarienne, surtout avant travail</td><td><span class=\"kw-alerte\">Détresse</span> <strong>immédiate</strong>, <span class=\"kw-clinique\">polypnée</span> prédominante, amélioration en quelques heures</td></tr>\n          <tr><td><strong>Inhalation méconiale</strong> <span class=\"q\">(jamais si liquide clair)</span></td><td>Nouveau-né à terme/post-terme · liquide amniotique méconial · <span class=\"kw-alerte\">asphyxie</span> périnatale</td><td><span class=\"kw-alerte\">Détresse</span> <strong>immédiate</strong>, <span class=\"kw-clinique\">évolution</span> potentiellement <span class=\"kw-alerte\">grave</span></td></tr>\n          <tr><td><strong>Infection néonatale</strong> (INBP)</td><td><span class=\"kw-def\">Facteurs de risque</span> d’INBP <span class=\"q\">(voir Zoom 2 ci-dessous)</span></td><td>Signes cliniques <strong>non spécifiques</strong></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Maladie des membranes hyalines</span></strong> (MMH)</td><td>Prématurité &lt; 32 SA · absence de <span class=\"kw-ttt\">corticothérapie</span> anténatale · parfois <span class=\"kw-etio\">diabète</span> maternel</td><td><span class=\"kw-alerte\">Détresse</span> <strong>très rapide</strong> après la naissance, aggravation progressive</td></tr>\n        </tbody>\n      </table>\n\n      <p><span class=\"kw-etio\">Pneumothorax</span> du nouveau-né : à évoquer devant une <strong>augmentation des pressions inspiratoires</strong> (sous <span class=\"kw-ttt\">VNI</span> avec PEP positive).</p>\n\n      <h4>Focus — Maladie des membranes hyalines (MMH)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Physiopathologie</span></strong></td><td><span class=\"kw-def\">Déficit en surfactant</span> → collapsus alvéolaire ; d’autant plus fréquente que l’enfant est <strong>immature</strong> (<span class=\"kw-chiffre\">80 %</span> avant <span class=\"kw-chiffre\">28 SA</span>)</td></tr>\n          <tr><td><strong>Clinique</strong></td><td><span class=\"kw-alerte\">Détresse</span> respiratoire aiguë <strong>sans intervalle libre</strong> par rapport à la naissance, avec <span class=\"kw-clinique\">geignement expiratoire</span></td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Radiographie</span></strong></td><td><span class=\"kw-imagerie\">Syndrome alvéolaire bilatéral</span> avec <span class=\"kw-imagerie\">bronchogramme aérien</span></td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Gazométrie</span></strong></td><td><span class=\"kw-bio\">Hypoxie</span> + <span class=\"kw-bio\">hypercapnie</span></td></tr>\n          <tr><td><strong>Prévention</strong></td><td><span class=\"kw-ttt\">Corticothérapie anténatale</span> maternelle si risque de prématurité avant <span class=\"kw-chiffre\">34 SA</span></td></tr>\n          <tr><td><strong>Traitement</strong></td><td><span class=\"kw-ttt\">Surfactant exogène</span> + <strong><span class=\"kw-ttt\">ventilation mécanique</span></strong> avec PEP (voie nasale ou endotrachéale)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Zoom 2 — Infection néonatale <span class=\"kw-etio\">bactérienne</span> précoce (INBP)</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Définition.</strong> Anciennement « <span class=\"kw-def\">infection maternofœtale</span> » (IMF). Contamination le plus souvent <strong>prénatale</strong> (transmission verticale) ; manifestations dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&lt; 3-7 premiers jours</span> de vie (le plus souvent <span class=\"kw-chiffre\">&lt; 48 h</span>).\n        <ul>\n          <li><strong>Voie vaginale ascendante</strong> : germes de la filière génitale (ex. SGB), lors d’une <span class=\"kw-clinique\">rupture prolongée des membranes</span> ou du passage dans la filière génitale maternelle</li>\n          <li><strong>Voie hématogène transplacentaire</strong> : listériose, <span class=\"kw-clinique\">pyélonéphrite</span>, <span class=\"kw-etio\">CMV</span>, rubéole…</li>\n        </ul>\n      </div>\n\n      <h4>Microbiologie</h4>\n\n      <ul>\n        <li><span class=\"kw-etio\">Streptocoque du groupe B</span> (<em>S. agalactiae</em>, SGB) <strong>++</strong> — bactérie la plus fréquemment en cause dans <span class=\"kw-clinique\">les</span> infections graves du nouveau-né</li>\n        <li><span class=\"kw-etio\">Escherichia coli</span> <strong>++</strong> — sérotype capsulaire <strong>K1</strong> le plus redoutable (méningites néonatales, septicémies)</li>\n        <li><span class=\"kw-etio\">Listeria monocytogenes</span></li>\n        <li><span class=\"kw-etio\">Entérocoque</span>, BGN, anaérobies : plus rares</li>\n      </ul>\n\n      <h4><span class=\"kw-def\">Facteurs de risque</span> d’INBP</h4>\n\n      <ul>\n        <li>Prélèvement vaginal maternel <strong>positif au SGB</strong> / absence d’<span class=\"kw-ttt\">antibioprophylaxie</span> adéquate</li>\n        <li><span class=\"kw-clinique\">Fièvre maternelle &gt; 38 °C</span> en per-partum ou dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 h</span> suivant l’accouchement (marqueur indirect de chorioamniotite)</li>\n        <li><span class=\"kw-alerte\">Prématurité</span> (dès &lt; 37 SA)</li>\n        <li>Liquide amniotique <strong>teinté</strong></li>\n        <li><span class=\"kw-alerte\">Rupture</span> prolongée des membranes (dès <span class=\"kw-chiffre\">12 h</span> de rupture)</li>\n      </ul>\n\n      <h4>Prévention — versant maternel</h4>\n\n      <table >\n        <thead>\n          <tr><th>Mesure</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Dépistage</span> du portage de SGB</strong></td>\n            <td>Prélèvement vaginal systématique entre <span class=\"kw-chiffre\">34-38 SA</span> (portage <span class=\"kw-chiffre\">10-15 %</span> des femmes enceintes). Écouvillon balayant la moitié inférieure du vagin → vestibule → vulve ; <strong>autoprélèvement possible</strong>, ni spéculum ni prélèvement anal. Inutile si autre indication d’ATB déjà présente (ATCD d’IMF à SGB, bactériurie à SGB)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Antibioprophylaxie</span> per-partum</strong></td>\n            <td>\n              Indiquée si : PV+ au SGB <em>ou</em> absence de PV · ATCD d’infection à SGB · bactériurie à SGB · accouchement &lt; 37 SA · RPM &gt;<span class=\"kw-chiffre\"> 12 h</span> · <span class=\"kw-clinique\">fièvre</span> &gt;<span class=\"kw-chiffre\"> 38 °C</span> pendant le travail.<br>\n              <span class=\"kw-ttt\">Pénicilline G, ampicilline, amoxicilline ou céfazoline</span> IV, à débuter <strong>&gt;<span class=\"kw-chiffre\"> 4 h</span> avant la naissance</strong> (si <span class=\"kw-ci\">allergie</span> : <span class=\"kw-ttt\">macrolides</span>) → réduit de <strong>&gt; ¾</strong> le risque <span class=\"kw-etio\">infectieux</span> néonatal\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Prise en charge — versant nouveau-né</h4>\n\n      <div class=\"callout callout-warn\">\n        <strong>Dogme.</strong> Tout nouveau-né <strong>symptomatique</strong> est suspect d’infection <strong>jusqu’à preuve du contraire</strong>. Il n’existe <strong>aucun signe clinique spécifique</strong> de l’INBP (difficulté diagnostique majeure).\n      </div>\n\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre ≥ 38 °C</span> (jamais banalisée à cet âge) ou <span class=\"kw-clinique\">hypothermie &lt; 36 °C</span></li>\n        <li><span class=\"kw-alerte\">Détresse</span> respiratoire · <span class=\"kw-clinique\">tachycardie / bradycardie</span> · signes d’hypoperfusion</li>\n        <li>Signes neurologiques : somnolence, irritabilité, hypotonie, <span class=\"kw-alerte\">convulsions</span></li>\n        <li>Signes digestifs : refus de boire, <span class=\"kw-clinique\">vomissements</span></li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-clinique\">Sepsis</span> néonatal</strong> — n’est pas la présentation la plus fréquente ; défini par <strong><span class=\"kw-chiffre\">≥ 2</span>/4</strong> critères :\n        <ul>\n          <li>Température <span class=\"kw-chiffre\">&gt; 38,5 °C</span> ou <span class=\"kw-chiffre\">&lt; 36 °C</span></li>\n          <li><span class=\"kw-clinique\">Tachycardie</span> <span class=\"kw-chiffre\">&gt; 180/min</span> ou <span class=\"kw-clinique\">bradycardie</span> <span class=\"kw-chiffre\">&lt; 100/min</span></li>\n          <li>FR <span class=\"kw-chiffre\">&gt; 50/min</span> ou <span class=\"kw-ttt\">ventilation mécanique</span></li>\n          <li>Leucocytose <span class=\"kw-bio\">&gt; 34 G/L</span></li>\n        </ul>\n      </div>\n\n      <h4>Bilan paraclinique</h4>\n\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Place</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Hémoculture</span></td><td>Diagnostic de certitude (bactérie pathogène dans le sang) — indiquée devant tout nouveau-né avec signe clinique d’INBP ou <span class=\"kw-alerte\">sepsis</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Ponction lombaire</span> (<span class=\"kw-bio\">LCS</span>)</td><td>Indications larges : <span class=\"kw-clinique\">AEG</span> · signes neurologiques · <span class=\"kw-alerte\">sepsis néonatal</span> · <span class=\"kw-bio\">hémoculture</span> positive · réponse partielle / absence d’amélioration <span class=\"kw-chiffre\">48 h</span> après le début des ATB</td></tr>\n          <tr><td><span class=\"kw-bio\">CRP</span></td><td>À distance de la naissance (<span class=\"kw-chiffre\">H12-H24</span>) — cinétique retardée par rapport au début de l’infection</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Ne sont plus recommandés.</strong>\n        <ul>\n          <li><span class=\"kw-bio\">NFS</span> systématique : valeur diagnostique médiocre</li>\n          <li><span class=\"kw-bio\">ECBU</span> : inutile <span class=\"kw-clinique\">les</span> 1ers jours de vie (utile seulement dans l’infection <strong>tardive</strong> &gt; <span class=\"kw-chiffre\">J7</span>)</li>\n          <li>Prélèvements périphériques (gastriques, orificiels)</li>\n        </ul>\n      </div>\n\n      <h4><span class=\"kw-ttt\">Antibiothérapie</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>Conduite</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Nouveau-né symptomatique</strong></td>\n            <td><span class=\"kw-ttt\">Bi-antibiothérapie IV</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-chiffre\">&lt; 1 h</span>) après bilan clinique, <span class=\"kw-ttt\">biologique</span> et bactériologique : <span class=\"kw-ttt\">amoxicilline + gentamicine</span>. <strong><span class=\"kw-def\">Réévaluation</span></strong> indispensable à <span class=\"kw-chiffre\">36-48 h</span> (interrompre / poursuivre / adapter)</td>\n          </tr>\n          <tr>\n            <td><strong>Nouveau-né asymptomatique</strong></td>\n            <td>Indications d’ATB <strong>exceptionnelles</strong> + <span class=\"kw-def\">surveillance</span> clinique codifiée en maternité. Chorioamniotite maternelle et INBP chez le jumeau <strong>ne sont plus</strong> des indications d’ATB immédiate</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 24 — Complications de la <span class=\"kw-ci\">grossesse</span> · 27 — Prévention risques fœtaux · 53 — Retard de croissance staturo-pondéral · 354 — Syndrome occlusif · 359 — <span class=\"kw-alerte\">Détresse</span> et insuffisance respiratoire aiguë</em></p>","frequence":5,"liens":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/pneumologie-cardiologie/detresse-respiratoire-aigue","label":"Collège Pédiatrie — Détresse respiratoire aiguë"},{"href":"https://radiopaedia.org/articles/neonatal-pneumothorax","label":"Radiopaedia : Neonatal pneumothorax"}]},{"id":"32-8","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir reconnaître une fente palatine et en connaître la fréquence","contenu":"<p>La <span class=\"kw-etio\">fente palatine</span> (ou <span class=\"kw-etio\">fente vélo-palatine</span>) est une <strong><span class=\"kw-def\">malformation congénitale</span></strong> de la cavité buccale, recherchée à l’examen clinique du nouveau-né dans le cadre de l’inspection de la <strong>bouche</strong> (cf. obj-0).</p>\n\n      <h4>Reconnaissance à l’examen clinique</h4>\n\n      <ul>\n        <li><strong>Inspection systématique de la bouche</strong> à la naissance et lors de l’examen du 8ᵉ jour</li>\n        <li>Visualisation directe d’une <strong><span class=\"kw-etio\">fente vélo-palatine</span></strong> ± associée à une <strong>brièveté du frein de langue</strong></li>\n        <li>Peut être <strong>isolée</strong> (fente palatine pure) ou s’intégrer à un <span class=\"kw-def\">syndrome polymalformatif</span> (rechercher d’autres anomalies à l’examen complet)</li>\n      </ul>\n\n      <h4>Fréquence</h4>\n\n      <ul>\n        <li><span class=\"kw-clinique\">Les</span> <span class=\"kw-etio\">fentes labio-palatines</span> concernent en moyenne <strong><span class=\"kw-chiffre\">1 naissance sur 750</span></strong></li>\n        <li><strong>Répartition des formes :</strong>\n          <ul>\n            <li>Formes <strong>unilatérales</strong> des palais primaire et secondaire : <span class=\"kw-chiffre\">≈ 40 %</span></li>\n            <li>Fentes <strong>isolées</strong> du palais primaire <em>ou</em> secondaire : <span class=\"kw-chiffre\">≈ 25 %</span> chacune</li>\n            <li>Fentes <strong>bilatérales</strong> du palais primaire (± palais secondaire) : <span class=\"kw-chiffre\">≈ 10 %</span></li>\n          </ul>\n        </li>\n        <li><span class=\"kw-clinique\">Les</span> fentes du palais primaire touchent plus souvent le <strong>garçon</strong>, du <strong>côté gauche</strong> (<span class=\"kw-chiffre\">3/1</span>)</li>\n        <li><strong>Causes plurifactorielles</strong> — accident de l’organogenèse entre la <span class=\"kw-chiffre\">5ᵉ et la 7ᵉ semaine</span> (<span class=\"kw-etio\">infectieux</span>, traumatique, <span class=\"kw-etio\">toxique</span>, métabolique, endocrinien, parfois <span class=\"kw-etio\">génétique</span>) → tableau isolé ou <span class=\"kw-def\">syndrome polymalformatif</span></li>\n      </ul>\n      <p class=\"obj-source-note\"><em>Source : Collège <span class=\"kw-ttt\">Chirurgie</span> maxillo-faciale &amp; stomatologie, ITEM 47, IV. Fentes labiopalatines (<span class=\"kw-def\">Épidémiologie</span>), p.75.</em></p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 88 — Dysphonie - Trouble de la parole</em></p>","frequence":2}],"astuces":[{"type":"danger","titre":"Fièvre du nouveau-né = urgence","contenu":"Toute <strong>T° <span class=\"kw-chiffre\">≥ 38 °C</span></strong> chez un nouveau-né est une <strong><span class=\"kw-alerte\">urgence</span> diagnostique</strong> qui justifie une <span class=\"kw-ttt\">antibiothérapie probabiliste</span> sans attendre. Ne jamais minimiser une <span class=\"kw-clinique\">fièvre</span> avant <span class=\"kw-chiffre\">3 mois</span> 🔥."},{"type":"danger","titre":"Anomalie de la différenciation sexuelle","contenu":"Devant une anomalie des OGE à la naissance : <strong>ne pas déclarer un sexe</strong> de façon précipitée. PEC dès <span class=\"kw-clinique\">les</span> 1ʳᵉˢ heures, rechercher systématiquement une <span class=\"kw-etio\">hyperplasie congénitale des surrénales</span> (risque d'insuffisance surrénale aiguë)."},{"type":"danger","titre":"Apgar : 3 temps obligatoires","contenu":"Le <span class=\"kw-def\">score</span> d'Apgar doit être noté à <strong>1, 5 ET <span class=\"kw-chiffre\">10 min</span></strong>. Un score <span class=\"kw-chiffre\">< 7</span> à 5 ou <span class=\"kw-chiffre\">10 min</span> impose des manœuvres de <span class=\"kw-alerte\">réanimation</span>. Piège ECN : confondre Apgar (vie extra-utérine) et score de Silverman (<span class=\"kw-alerte\">détresse</span> respiratoire)."},{"type":"warn","titre":"Cordon ombilical : 2 artères + 1 veine","contenu":"Toujours vérifier la présence de <strong>2 artères et 1 veine</strong> ombilicales (moyen mémo : <em>« tu as de la veine d'avoir 2 artères »</em>). Une <strong>artère ombilicale unique</strong> doit faire rechercher d'autres malformations."},{"type":"warn","titre":"Chute du cordon > 1 mois","contenu":"Une chute du cordon retardée <strong>au-delà d'<span class=\"kw-chiffre\">1 mois</span></strong> doit faire <span class=\"kw-alerte\">rechercher un déficit immunitaire</span> ⚠️ (notamment une anomalie de l'adhésion leucocytaire)."},{"type":"warn","titre":"Pied bot vs malposition","contenu":"Distinguer impérativement :\n        <ul>\n          <li><strong>Déformation rigide non réductible</strong> = <span class=\"kw-etio\">pied bot varus équin</span> (malformation, PEC orthopédique précoce).</li>\n          <li><strong>Déformation réductible</strong> = pied varus, clinodactylie (malposition posturale bénigne secondaire aux contraintes utérines).</li>\n        </ul>"},{"type":"warn","titre":"Guthrie : refus parental possible","contenu":"Le test de Guthrie <strong>n'est pas obl<span class=\"kw-chiffre\">iga</span>toire</strong>. Le <span class=\"kw-def\">consentement écrit des parents</span> est sollicité (recherche <span class=\"kw-etio\">génétique</span> CFTR si trypsine élevée). Refus = signature d'une décharge."},{"type":"info","titre":"Mémo des 6 dépistages Guthrie : « PM-HH-DD »","contenu":"<strong>P</strong>hénylcétonurie · <strong>M</strong>ucoviscidose · <strong>H</strong>ypothyroïdie <span class=\"kw-etio\">congénitale</span> · <strong>H</strong>yperplasie congénitale des surrénales · <strong>D</strong>éficit en MCAD · <strong>D</strong>répanocytose. Prélèvement vers <span class=\"kw-chiffre\">72 h</span> (impérativement &gt;<span class=\"kw-chiffre\"> 48 h</span>)."},{"type":"info","titre":"Automatismes primaires","contenu":"Leur <strong>absence est toujours pathologique</strong>. En revanche, leur <strong>présence ne témoigne pas</strong> de l'intégrité du SNC. Disparition normale entre <span class=\"kw-chiffre\">2 et 4 mois</span>."},{"type":"info","titre":"OEAP : faux négatifs possibles","contenu":"<span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">OEAP</span> peuvent être <strong>normales chez un enfant réellement sourd</strong> (neuropathie auditive). Toujours réinterroger les parents sur les réactions auditives de l'enfant lors des consultations de <span class=\"kw-def\">suivi</span>."},{"type":"tip","titre":"Examen du 8ᵉ jour","contenu":"L'examen obl<span class=\"kw-chiffre\">iga</span>toire est à effectuer <strong>avant le 8ᵉ jour</strong> de vie : il établit le <span class=\"kw-def\">certificat du 8ᵉ jour</span>. À faire en présence des parents, pièce claire et chauffée, avant un repas, enfant éveillé."},{"type":"tip","titre":"Sortie de maternité — 4 piliers à prescrire","contenu":"<ol>\n        <li>Soins du cordon jusqu'à sa chute.</li>\n        <li>Supplémentations vitaminiques (<span class=\"kw-ttt\">vitamine K, vitamine D</span>).</li>\n        <li>Régime précis d'alimentation lactée.</li>\n        <li>Pesée hebdomadaire le 1ᵉʳ mois si <span class=\"kw-ci\">allaitement</span> + consultation pédiatre à<span class=\"kw-chiffre\"> 2 semaines</span>.</li>\n      </ol>"}],"strategie":{"urgence":"<p><strong>Inadaptation à la vie extra-utérine</strong></p><p><span class=\"kw-ttt\">manœuvres de réanimation néonatale</span> sans délai</p><ul><li><span class=\"kw-def\">Score d'Apgar</span> &lt; <span class=\"kw-chiffre\">7</span> (évalué à <span class=\"kw-chiffre\">1, 5 et 10 min</span>) → <span class=\"kw-alerte\">inadaptation</span>, concerne <span class=\"kw-chiffre\">5–10 %</span> des nouveau-nés</li><li>Présence obl<span class=\"kw-chiffre\">iga</span>toire à chaque naissance d'<span class=\"kw-ttt\">≥ 1 personne entraînée</span> aux 1ers gestes, dédiée à ce nouveau-né</li></ul><p><strong><span class=\"kw-clinique\">Fièvre</span> du nouveau-né <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> diagnostique</span></strong></p><ul><li><span class=\"kw-alerte\">Température ≥ 38 °C</span>, a fortiori <span class=\"kw-alerte\">fièvre avant 3 mois</span></li><li>Justifie une <span class=\"kw-ttt\">antibiothérapie probabiliste</span></li></ul><p><strong>Délais critiques des dépistages</strong></p><ul><li><span class=\"kw-def\">Guthrie</span> autour de <span class=\"kw-chiffre\">72 h</span> (impérativement <span class=\"kw-chiffre\">&gt; 48 h</span>, avant la sortie de maternité)</li><li>Surdité — <span class=\"kw-def\">OEAP</span>/<span class=\"kw-def\">PEAA</span> dès <span class=\"kw-chiffre\">J3</span></li><li><span class=\"kw-ttt\">L-thyroxine</span> de l'hypothyroïdie <span class=\"kw-etio\">congénitale</span> débutée <span class=\"kw-chiffre\">avant J12–15</span></li></ul>","hospit":"<p><strong>PEC spécialisée immédiate</strong></p><ul><li>Toute <span class=\"kw-alerte\">situation à risque ou pathologique</span> → transfert en <span class=\"kw-ttt\">unité de néonatologie / réanimation néonatale</span></li></ul><p><strong>Orientations selon le <span class=\"kw-def\">dépistage</span></strong></p><ul><li>Mucoviscidose → <span class=\"kw-ttt\">CRCM</span> (centre de ressources et de compétences)</li><li>Surdité (OEAP/PEAA anormaux) → <span class=\"kw-ttt\">ORL</span> puis <span class=\"kw-ttt\">centre d'audiologie pédiatrique</span></li><li>Cryptorchidie · fente palatine → <span class=\"kw-ttt\">chirurgien pédiatre</span></li><li>HCS, cryptorchidie bilatérale non palpable → <span class=\"kw-ttt\">pédiatre endocrinologue</span></li></ul><p><strong>Sortie de maternité</strong></p><ul><li>Examen obl<span class=\"kw-chiffre\">iga</span>toire <span class=\"kw-chiffre\">avant J8</span> → <span class=\"kw-def\">certificat du 8e jour</span> + mise à jour du <span class=\"kw-def\">carnet de santé</span></li><li>Consultation avec un <span class=\"kw-ttt\">pédiatre</span> recommandée à la <span class=\"kw-chiffre\">2e semaine de vie</span></li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Fièvre ≥ 38 °C avant 3 mois</span> · gêne respiratoire · difficultés alimentaires</li><li><span class=\"kw-alerte\">Absence de pouls fémoraux</span> → <span class=\"kw-etio\">coarctation de l'aorte</span></li><li><span class=\"kw-alerte\">Leucocorie</span> (absence de lueur pupillaire) → <span class=\"kw-etio\">rétinoblastome</span>, <span class=\"kw-etio\">cataracte congénitale</span></li><li><span class=\"kw-alerte\">Chute du cordon &gt; 1 mois</span> → <span class=\"kw-etio\">déficit immunitaire</span></li><li><span class=\"kw-alerte\">OGE ambigus</span> → <span class=\"kw-etio\">hyperplasie congénitale des surrénales</span> (PEC dès <span class=\"kw-clinique\">les</span> 1res heures)</li><li><span class=\"kw-alerte\">Absence des réflexes archaïques</span> (toujours pathologique)</li><li>Retard d'émission : <span class=\"kw-alerte\">méconium &gt; 48 h</span> · <span class=\"kw-alerte\">1res urines &gt; 24 h</span></li><li>Anomalie de fermeture du tube neural : <span class=\"kw-clinique\">déviation du sillon interfessier</span>, <span class=\"kw-clinique\">pertuis</span>, <span class=\"kw-clinique\">lipome sous-cutané</span>, <span class=\"kw-clinique\">touffe de poils</span></li><li>Limitation de l'<span class=\"kw-clinique\">abduction de hanche &lt; 60°</span> → <span class=\"kw-etio\">luxation congénitale de hanche</span></li></ul>","principes":"<p>Soins systématiques en salle de naissance + <span class=\"kw-ttt\">dépistages néonatals systématiques</span> + éducation à la puériculture.</p><p><strong>Soins systématiques en salle de naissance</strong></p><ul><li>1er temps : clampage/section du cordon, <span class=\"kw-def\">Apgar</span>, <span class=\"kw-ttt\">mise au sein</span> dans la 1re heure, prévention de l'<span class=\"kw-clinique\">hypothermie</span> (<span class=\"kw-chiffre\">24 °C</span>, séchage, bonnet, peau-à-peau)</li><li>2nd temps : <span class=\"kw-ttt\">vitamine K1 per os</span>, bracelets d'identification, examen + mesures (<span class=\"kw-chiffre\">TN/PN/PCN</span>), soins du cordon (<span class=\"kw-chiffre\">2 artères + 1 veine</span>)</li></ul><p><strong>Soins non systématiques <span class=\"q\">— selon signe d'appel</span></strong></p><ul><li><span class=\"kw-ttt\">Collyre antibiotique</span> si ATCD/FR d'<span class=\"kw-clinique\">IST</span> parentale</li><li><span class=\"kw-ttt\">Sonde d'aspiration</span> si <span class=\"kw-clinique\">dyspnée</span> inspiratoire / désaturation aux cris → atrésie des choanes</li><li><span class=\"kw-ttt\">Test à la seringue</span> si hypersialorrhée / hydramnios → atrésie de l'œsophage</li></ul><p><strong>Dépistages systématiques</strong></p><ul><li><span class=\"kw-def\">Guthrie</span> : <span class=\"kw-bio\">6 maladies</span> (phénylcétonurie, hypothyroïdie, HCS, mucoviscidose, déficit en MCAD, drépanocytose)</li><li>Surdité (<span class=\"kw-def\">OEAP</span>/<span class=\"kw-def\">PEAA</span>), <span class=\"kw-clinique\">luxation congénitale de hanche</span> à chaque examen, examen des <span class=\"kw-clinique\">yeux</span></li></ul>","suivi":"<p><strong>Maternité :</strong> mise à jour du <span class=\"kw-def\">carnet de santé</span> + <span class=\"kw-def\">certificat du 8e jour</span>.<br><strong>Sortie :</strong> ordonnance (soins du cordon, supplémentations <span class=\"kw-ttt\">vitaminiques</span>, régime lacté précis).<br><strong>Domicile :</strong> <span class=\"kw-clinique\">poids</span> <span class=\"kw-chiffre\">1×/semaine le 1er mois</span> si <span class=\"kw-ci\">allaitement</span> · consultation <span class=\"kw-ttt\">pédiatre</span> à la <span class=\"kw-chiffre\">2e semaine</span> · prévention MIN (couchage dorsal, <span class=\"kw-etio\">tabagisme passif</span>).</p>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/neonatologie/prise-charge-du-nouveau-ne","label":"Collège Pédiatrie — Prise en charge du nouveau-né"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Nouveau-né à la naissance — Évaluation de l'adaptation : score d'Apgar à 1, 5 et 10 min","detail":"<h4>CAT en salle de naissance — Adaptation à la vie extra-utérine + soins ciblés du nouveau-né</h4>","branches":[{"to":"t-rea","label":"Apgar < 7 — inadaptation (5–10 %)","color":"red"},{"to":"q-appel","label":"Apgar ≥ 7 — nouveau-né vigoureux","color":"green"}]},{"id":"t-rea","kind":"terminal","label":"Manœuvres de réanimation néonatale","color":"red","detail":"<h4>Repérage</h4><ul><li><span class=\"kw-alerte\">Apgar &lt; 7</span> : coloration <span class=\"kw-clinique\">bleue/pâle</span>, <span class=\"kw-clinique\">FC &lt; 100 bpm</span>, hypotonie, respiration absente ou lente</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Réanimation néonatale</span> immédiate par la personne entraînée présente, sur <span class=\"kw-ttt\">table radiante</span></li></ul><h4>Délai</h4><ul><li>Immédiat</li></ul>"},{"id":"q-appel","kind":"decision","label":"Signe d'appel clinique ou anamnestique ? — Oriente vers un soin non systématique ciblé","branches":[{"to":"t-oesophage","label":"Hypersialorrhée · gêne respi · hydramnios","color":"amber"},{"to":"t-choanes","label":"Dyspnée inspiratoire · désaturation aux cris","color":"amber"},{"to":"t-atb","label":"ATCD / FR d'IST chez les parents","color":"amber"},{"to":"t-systematique","label":"Examen initial normal","color":"green"}]},{"id":"t-oesophage","kind":"terminal","label":"Test à la seringue → atrésie de l'œsophage","color":"amber","detail":"<h4>Principe</h4><ul><li>Injecter rapidement de l'<span class=\"kw-ttt\">air dans une sonde orogastrique</span>, ausculter le creux ép<span class=\"kw-chiffre\">iga</span>strique</li></ul><h4>Interprétation</h4><ul><li><span class=\"kw-alerte\">Absence de bruit aérique</span> ép<span class=\"kw-chiffre\">iga</span>strique = atrésie de l'œsophage</li></ul>"},{"id":"t-choanes","kind":"terminal","label":"Sonde d'aspiration → atrésie des choanes","color":"amber","detail":"<h4>Indication</h4><ul><li><span class=\"kw-clinique\">Dyspnée inspiratoire</span> et/ou <span class=\"kw-clinique\">désaturation cédant aux cris</span></li></ul><h4>Geste</h4><ul><li><span class=\"kw-ttt\">Sonde d'aspiration</span> à la recherche d'une atrésie des choanes</li></ul>"},{"id":"t-atb","kind":"terminal","label":"Antibioprophylaxie conjonctivale","color":"amber","detail":"<h4>Indication</h4><ul><li><span class=\"kw-etio\">ATCD ou facteurs de risque d'IST</span> chez <span class=\"kw-clinique\">les</span> parents (<span class=\"kw-ci\">grossesse</span> non/mal suivie)</li></ul><h4>Geste</h4><ul><li><span class=\"kw-ttt\">Collyre antibiotique</span> en prophylaxie</li></ul>"},{"id":"t-systematique","kind":"terminal","label":"Soins systématiques seuls","color":"green","detail":"<h4>1er temps</h4><ul><li>Clampage/section du cordon</li><li><span class=\"kw-ttt\">Mise au sein</span> dans la 1re heure si <span class=\"kw-ci\">allaitement</span></li><li>Prévention de l'<span class=\"kw-clinique\">hypothermie</span> :<span class=\"kw-chiffre\"> 24 °C</span>, séchage, bonnet, peau-à-peau</li></ul><h4>2nd temps</h4><ul><li><span class=\"kw-ttt\">Vitamine K1 per os</span></li><li>Bracelets d'identification</li><li>Examen + mesures (<span class=\"kw-chiffre\">TN/PN/PCN</span>)</li><li>Soins du cordon : <span class=\"kw-chiffre\">2 artères + 1 veine</span></li></ul>"}]},"cards":[]};